--!strict
local Players=game:GetService("Players");local Race=require(script.Parent.Services.RaceService);local Maps=require(script.Parent.Services.MapService);local remotes=require(script.Parent.Services.RemoteService).Ensure();local prompt:{[Player]:boolean}={}
local function playerFrom(hit:BasePart):Player?local n:Instance?=hit;while n and n~=workspace do if n:IsA("Model")and n:FindFirstChildOfClass("Humanoid")then return Players:GetPlayerFromCharacter(n)end;n=n.Parent end;return nil end
Maps.Loaded.Event:Connect(function(_,map)local finish=map:FindFirstChild("FinishLine");local checkpoints=map:FindFirstChild("Checkpoints");if not finish or not finish:IsA("BasePart")or not checkpoints then return end;local required=#checkpoints:GetChildren();finish.Touched:Connect(function(hit)local p=playerFrom(hit);local d=p and Race.Get(p);if not p or not d or Race.State~="Racing"or not d.IsRacing or d.IsFinished then return end;if d.CurrentCheckpoint<required then if not prompt[p]then prompt[p]=true;remotes.PlayerFinished:FireClient(p,{blocked=true,message="請先通過所有檢查點"});task.delay(2,function()prompt[p]=nil end)end;return end;Race.FinishCount+=1;d.IsFinished=true;d.HasFinished=true;d.IsRacing=false;d.FinishPlace=Race.FinishCount;d.FinishTime=os.clock()-d.StartTime;print(string.format("[Finish] %s finished place %d",p.Name,d.FinishPlace));remotes.PlayerFinished:FireAllClients({userId=p.UserId,displayName=p.DisplayName,finishPlace=d.FinishPlace,finishTime=d.FinishTime});Race.ProgressChanged:Fire(p);if Race.AllFinished()then Race.AllRacersFinished:Fire()end;local area=map:FindFirstChild("FinishWaitingArea");if area and area:IsA("BasePart")then Race.Teleport(p,area.CFrame)end end)end)
